 static JSONObject input(String request)throws Exception{return SyntheticBusinessData.object().put("request_id",request).put("customer_id","qa_c").put("title","QA Gartenpflege").put("starts_at","2030-01-07T08:00:00Z").put("ends_at","2030-01-07T10:00:00Z").put("timezone","Europe/Vienna").put("weather_profile","lawn").put("status","tentative");}
 static JSONObject row(OwnerNativeAcceptance.Fixture f,String id)throws Exception{return PixelMcpWriteTools.find(PixelMcpReadTools.effective(f.store.getState()).getJSONArray("appointments"),id);}
 static final class Provider implements DriveRestClient.Wire {
  JSONObject event;int creates,patches;boolean lose,stale,expired,deny;int lists;
  DriveRestClient.Reply reply(int status,JSONObject body)throws Exception{return new DriveRestClient.Reply(status,body==null?new byte[0]:body.toString().getBytes(StandardCharsets.UTF_8),new HashMap<>());}
  public DriveRestClient.Reply send(String method,String url,Map<String,String> headers,byte[] body,int max)throws Exception{
   if(deny)return reply(401,null);
   if(method.equals("GET")&&url.contains("maxResults")){lists++;if(expired){expired=false;return reply(410,null);}return reply(200,SyntheticBusinessData.object().put("items",event==null?new JSONArray():new JSONArray().put(event)).put("nextSyncToken","next-"+lists));}
   if(method.equals("GET"))return reply(event==null?404:200,event);
   if(method.equals("POST")){if(event!=null)return reply(409,null);creates++;event=SyntheticBusinessData.object(new String(body,StandardCharsets.UTF_8)).put("etag","v1");if(lose){lose=false;throw new java.io.IOException("Synthetic ACK loss");}return reply(200,event);}
   if(method.equals("PATCH")){if(stale)return reply(412,null);if(!headers.get("If-Match").equals(event.getString("etag")))throw new AssertionError("ETag omitted");patches++;event=SyntheticBusinessData.object(new String(body,StandardCharsets.UTF_8)).put("etag","v"+(patches+1));return reply(200,event);}
   if(method.equals("DELETE")){if(stale)return reply(412,null);event=null;return reply(204,null);}throw new AssertionError("Unexpected synthetic request");
  }
 }
